CREATE TABLE _galope_bootstrap (fresh INTEGER NOT NULL);
INSERT INTO _galope_bootstrap(fresh) SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='store') AND NOT EXISTS (SELECT 1 FROM products) AND NOT EXISTS (SELECT 1 FROM orders);
